-- For any valid date string in T2.c13, both date filtering conditions will yield the same boolean result.
-- The STRFTIME function in SQLite is consistent in extracting year and month components, whether separately or combined.

-- Example data that would yield the same result for both queries (e.g., c23 = 1 for both):
INSERT INTO table3 (c23, c1) VALUES (1, '-');
